quests[9389] = { id = 9389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickering Flames in the Eastern Kingdoms", description = "The Midsummer Fire Festival traditionally lights up the land with a myriad of flames. Some argue that the green fires are the finest, as they are the hardest to maintain and have such a distinctive hue.\n\nMake sure they still burn in the Eastern Kingdoms for our Flamekeeper. They sit near Dun Modr in the Wetlands, close to Pyrewood Village within Silverpine Forest, on the cliffs overlooking the lighthouse in Westfall, and by the ruined tower in Hillsbrad Foothills.", sourceObjective = "Visit the bonfires within Hillsbrad Foothills, Silverpine Forest, Westfall, and the Wetlands, then speak with the Festival Flamekeeper.", progress = "Have you seen to your task?", completion = "So you've returned, and you've seen to the emerald flames of the continent. What do you think, mm? A rare and wonderful sight, to be certain. I am aware, however, that tangible rewards are better appreciated... so please, take this for your trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[9415] = { id = 9415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Marshal Bluewall", description = "Are you Marshal Bluewall's new recruits? Of course you are.\n\nWhat are you waiting for? Good soldiers are dying in the desert. Aren't you excited to join them?\n\nNow, get going and don't dry out on the way.", sourceObjective = "Speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.", completion = "The Alliance needs every able body they can get. The Horde has been receiving a steady supply of reinforcements from the northern part of the continent, and it's been a struggle to keep up.\n\nLet me explain the situation to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9416] = { id = 9416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to General Kirika", description = "You must be one of General Kirika's new recruits. It's about time you showed up. Bodies wear down quick in the desert.\n\nThe dwarves have been getting reinforcements daily, and we can't afford to lose ground in our struggle for resources in Silithus.\n\nGet your instructions from the General. It's not my job to train you, just find you.", sourceObjective = "Speak with General Kirika at the Horde encampment near Hive'Regal.", completion = "It's good that you're hear, but there's no time to waste making small talk. You need instructions, and then you need to get out there.\n\nListen up.", sourceObjectiveStatus = "unverified-source-field" }
quests[9419] = { id = 9419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouring the Desert", description = "We recently found out that the Horde has been scavenging the Silithus desert for resources, but paid them little mind. We thought it could not be worth it to station large numbers in this sweltering desert.\n\nHowever, it was discovered the importance of the resources, and now we are scrambling to catch up.\n\nIf I have your assistance, you must go into the desert and recover the silithyst and return it here.", sourceObjective = "Find and deliver Silithyst to the Silithyst Extractor, then speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.", progress = "Be careful out there, but also be quick. We have no time to lose.", completion = "Thank the Light you were successful.\n\nNow if we could only have started this sooner, our need would not be so desperate. We must keep the bounty of the desert from falling into the hands of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[9422] = { id = 9422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouring the Desert", description = "For some time now, we have been tapping the crystal resources of the Silithus desert. The only dangers we faced were from the creatures that made this place their home and the oppressive sand and dust and heat.\n\nBut now the Alliance seems to have caught on to what we have found here. It is now a race between us to capture the natural resources, and keep them from the other.\n\nI need every set of hands that is available. I hope I have yours.", sourceObjective = "Find and deliver Silithyst to the Silithyst Extractor then speak with General Kirika at the Horde encampment near Hive'Regal.", progress = "Be wary of the dangers of the desert, {name}. With the Alliance lurking in the dunes, any step could be your last.", completion = "You've done well, {name}. These resources will be added to our stockpiles, and every bit is to our gain and our enemy's loss.", sourceObjectiveStatus = "unverified-source-field" }
quests[9556] = { id = 9556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Victor...", description = "You've no doubt been fighting long and hard among the towers, {race}. We would like to give something back to you in return for your defense of these lands, but first, you must prove to us you understand the weight of the tragedies that took place here.\n\nWalk the streets of Stratholme and find a vial of the holy water. Once you have it, travel to the mage quarter of Stormwind or the Undercity... There, if you are victorious within these lands, you will find my colleague.", sourceObjective = "Collect a bottle of Stratholme Holy Water from within the city of Stratholme and deliver it to the Lordaeron Mage within the Mage Quarter of Stormwind or the Undercity when your side is victorious in the Eastern Plaguelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[9664] = { id = 9664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Establishing New Outposts", description = "Welcome to the Plaguelands, {name}. As you know, the Forsaken and their allies hold the lands to the west of here against our best efforts. The Alliance commanders have decided that here in the east, we will establish new fortifications to tighten the noose around our enemies.\n\nTowers long abandoned since the days of Lordaeron are to be seized and rebuilt for this purpose. These lands are dangerous, and we could use your help.", sourceObjective = "Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Whitebeard at Light's Hope Chapel.", completion = "Very good, {name}. It will be important for us to hold these towers against future attacks, and for that we may need your assistance until reinforcements can be brought in to secure the area.", sourceObjectiveStatus = "unverified-source-field" }
quests[9665] = { id = 9665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolstering Our Defenses", description = "Agents of the Forsaken uncovered an Alliance plot to establish new bases here in the Eastern Plaguelands, at abandoned towers throughout the area.\n\nIt is imperative that we not allow them to establish a significant presence on our eastern borders, and so we must stave off this Alliance incursion. Our current plans are to drive them out of any towers they may have already seized, and occupy those that we have under our control against further attacks.", sourceObjective = "Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Gormok at Light's Hope Chapel.", completion = "This is good news, {name}. It will be a constant struggle here in the Plaguelands until we have fully driven back the forces of the Alliance.\n\nUntil that day, I hope that we will have your continued assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[65593] = { id = 65593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hearts of the Lovers", description = "An incubus will be drawn to the hearts of lovers, and the most aching love will create the most irresistible lure.\n\nMy scrying has revealed two that should serve exceptionally.\n\nIn Silverpine Forest, Avelina Lilly provides her tailoring services to the fallen wizards at Ambermill. In the Barrens, Isaac Pearson hopes to make his mark in the seaside town of Ratchet.\n\nThey toil on opposite ends of the world, yet their hearts yearn only for each other. Bring those hearts to Carendin.", sourceObjective = "Bring the hearts of Avelina Lilly and Isaac Pearson to Carendin Halgar in the Temple of the Damned.", progress = "Ah, {name}, you return. Were you able to procure the lovers' hearts?", completion = "As expected. Excellently done, {name}.\n\n\n\nIdiots.", sourceObjectiveStatus = "unverified-source-field" }
quests[65597] = { id = 65597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "The time has come at last. Bring the hearts to the summoning circle below. Place them at its center and call forth the incubus.\n\nThe demon will not be pleased when it realizes that you have tempted it into a trap. Do not fall prey to its beguilement, {name}. You must subdue it fully.\n\nOnly then can I teach you the spell to bind it to your will.", sourceObjective = "Using the Lovers' Hearts, summon and subdue an incubus, then return the Lovers' Hearts to Carendin Halgar in the Magic Quarter of the Undercity.", progress = "The incubus possesses martial prowess, but its illusory charms are its most potent weapon. Falter for even a moment, and the demon will seize upon the opportunity to enthrall you.\n\nDo not let it, {name}.", completion = "Impressive. Very impressive. The sayaad specialize in preying upon mortals. Many a {class} has thought themselves strong enough to command one, only to find themselves being commanded instead.\n\nThis trial did not break you, {name}, and your efforts have earned your reward. I will teach you the spell to summon the incubus.", sourceObjectiveStatus = "unverified-source-field" }
quests[65601] = { id = 65601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love Hurts", description = "A sayaad male is known as an incubus. A creature of profound evil and singular mind.\n\nThe demon must be lured into our world with an item of enticement - an object that represents great love and devotion.\n\nIf you trust a blind man to lead you, {name}, then listen. East from the Cleft of Shadow, along the main drag of Orgrimmar, lives Magar. He longs for the return of his mate, Krilge.\n\nSeek him out. He'll ask you to search for something precious. That is the key which you must bring to Gan'rul.", sourceObjective = "Speak with Magar in Orgrimmar.", completion = "Who told you about Krilge? Have you come with any news? You better not be toying with me...", sourceObjectiveStatus = "unverified-source-field" }
quests[65602] = { id = 65602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Is Love?", description = "You will need a powerful reagent to tempt an incubus -- an object that represents great devotion and love.\n\nWith my scrying, I have located a small figurine that should be suitable for your ritual.\n\nThousands of years ago, the figurine belonged to a young couple. The original owners are no more, but their keepsake has survived to the present day.\n\nFollow the road north into Ashenvale, then west and past Maestra's Post. You will see a house nestled amongst the trees. There you will find what you seek.", sourceObjective = "Retrieve the Wooden Figurine and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.", progress = "You've returned. Successfully, I assume?", completion = "<Gakin turns the wooden figurine over in his hand.>\n\nI sense the emotional energy residing within this artifact, undiminished by the passing of time. The incubus will be drawn to it like a fly to honey.\n\nTakar never disappoints.", sourceObjectiveStatus = "unverified-source-field" }
quests[65603] = { id = 65603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "The time has come. Take the figurine and descend into the crypts below. A summoning circle has been prepared, and you must place the figurine at its center.\n\nThen the gateway will open, and the incubus will cross into our world.\n\nA sayaad is not to be underestimated. The demon will not hesitate to attack when it realizes your ruse. You must draw upon all you have been taught to defeat it.\n\nIf you succeed, return to me and I shall bind the creature to your will. Fail, and your soul is forfeit.", sourceObjective = "Using the Wooden Figurine, summon and subdue an incubus, then return the Wooden Figurine to Gakin the Darkbinder in the Slaughtered Lamb.", progress = "The incubus will try to lower your guard through beguilement and deception. The demon is adept at swaying the hearts of mortals.\n\nRemember that anything it may offer you is false. To the demon, you are merely prey.", completion = "Not bad, {name}. Your have bested the fiend, and your will remains unbroken.\n\nMany a {class} has believed themselves strong enough to bind a sayaad, only to become the demon's next meal instead. I am pleased to see you are not so foolish.\n\nWatch closely, and I will teach you the invocation to call upon your newly bound incubus.", sourceObjectiveStatus = "unverified-source-field" }
quests[65604] = { id = 65604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "Yes... I see. I feel the residual emotions bound within these threads. Love is woven into its stitches. The incubus will not be able to resist.\n\nTake this to the summoning circle in Neeru's tent, {name}. Summon forth a malevolent incubus, then show it your mastery. Do not expect it to be subdued quietly. Ready your magic and prepare yourself for a fight. Underestimating a demon has been many a warlock's final mistake.\n\nWhen you have defeated it, return the cloth to me. I will let Magar know what you found.", sourceObjective = "Using the Withered Scarf, summon and subdue an incubus, then return the Withered Scarf to Gan'rul Bloodeye in Orgrimmar.", progress = "The sayaad are dominators of minds and torturers of souls. Their visage brings the heart joy, leaving you defenseless when they rend your flesh with whip and claw.\n\nDo not entertain the incubus' charms, {name}. Slay it quickly and let it be done.", completion = "Hah! Victorious, as expected!\n\nThe incubus is subdued, and it will be my pleasure to teach you to summon the demon. You strength is growing, and I have no doubt that this is a mere stepping stone to even greater powers.\n\nI will return the scarf to Magar. I have known that orc for many years, and never did I think he would care for someone the way he cared for Krilge.\n\nIt is a reminder of what separates us from the demons. We wield their darkness, but they will never wield us.", sourceObjectiveStatus = "unverified-source-field" }
quests[65610] = { id = 65610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wish You Were Here", description = "I met Krilge while making Mooncloth in Ashenvale. He was stationed there to protect civilians from danger, until he disappeared...\n\nThey've stopped looking for him and consider him a deserter, but I don't believe it.\n\nWe would often meet at Fallen Sky Lake before it became overrun by those aggressive bog beasts.\n\nI'm not typically one to ask favors, but if you could go to Ashenvale and look for any sign of him, I'd appreciate it.", sourceObjective = "Investigate Fallen Sky Lake in Ashenvale and report your findings to Gan'rul Bloodeye in Orgrimmar.", progress = "Yes, what is it?", completion = "What is it you have there, {name}? A scarf made of... Mooncloth? You best not be seeking to romance me.", sourceObjectiveStatus = "unverified-source-field" }
quests[76156] = { id = 76156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalk With The Earthmother", description = "I sense in you a hidden talent for the subtle arts, {class}. Use this mask to infiltrate the nearby Venture Company mine and steal their supplies. It may not seem like a convincing disguise, but a skilled rogue can slip past any guard with naught but a winning smile and a cunning distraction. I believe this capability lies within you as well.", sourceObjective = "Sneak into the Venture Company mine southeast of Thunder Bluff and collect 5 Seaforium Mining Charges from carts of blasting supplies, then return them to Boarton Shadetotem in Thunder Bluff.", progress = "We'll need to work on your stealth skills, {class}.  I heard you approaching as soon as you set foot on the mesa.", completion = "Hmm... perhaps disguises are not your strength.", sourceObjectiveStatus = "unverified-source-field" }
quests[76160] = { id = 76160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalk With The Earthmother", description = "Maybe your skills lie with poisons, not disguises. The Harpies to the north nest in a tree which produces a resin of potent toxicity. Gather the fallen cones around the nests, then crush them into a salve. When applied to a blade this salve will sear your opponent's wounds into their flesh and turn their blood to salt.", sourceObjective = "Gather 8 Windfury Cones north of Thunder Bluff, use them with the Mortar and Pestle, then return to Boarton Shadetotem in Thunder Bluff with the result.", progress = "Be careful with the salve once you are finished, {class}.  Even skin contact could be quite painful.", completion = "{class}, this is not the venomous salve I asked for.  What you have brought me is pine nut butter.  Are you sure you followed my instructions?\n\nThis will be of far more use spread on some spice bread than on a dagger.  Although you would be quite formidable against a foe with a nut allergy.", sourceObjectiveStatus = "unverified-source-field" }
quests[76240] = { id = 76240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalk With The Earthmother", description = "I have one last idea that may lead us to success. I still feel there is hidden talent in you, but let us try and coax it out with a less direct approach.\n\nGo and procure a Raw Brilliant Smallfish, then bring it back here. Use these daggers to clean and fillet it. Do not think too hard - do what comes naturally.", sourceObjective = "Buy or catch a Raw Brilliant Smallfish, then use the Knife Set to fillet it in front of Boarton Shadetotem in Thunder Bluff.", progress = "Do you have something for me?", completion = "That was quite a display, {class}.  Not the rogueish precision I hoped for, but you possess an impressive ambidexterity.\n\nI see now that you will not be the one to train my people in the subtle arts, but there is one thing I can teach you.  Good luck on your travels, {class}.  The Horde will need heroes like you.", sourceObjectiveStatus = "unverified-source-field" }
quests[78088] = { id = 78088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Artifact", description = "<The mysterious orb you hold fills you with cold dread. You can almost hear a voice echo faintly in your mind. Low and guttural, you understand well that the language being spoken is demonic in nature. \n\nEven as a paladin, this magic is beyond you. Find a more senior paladin here in Kalimdor who might be able to help you discern the nature of this sinister object.>", sourceObjective = "Bring the Althalaxx Orb to Delgren the Purifier at Maestra's Post in Ashenvale.", progress = "Did you find something in the tower?", completion = "You were right to bring this to me, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78089] = { id = 78089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advice From Stormwind", description = "There's a powerful darkness about this orb. Its nature is clearly demonic, but past that it is beyond my ability to discern its purpose.\n\nTake the orb to the one known as Katherine the Pure in the Stormwind Cathedral. Consult with her for advice on the orb.", sourceObjective = "Bring the Althalaxx Orb to Katherine the Pure in Stormwind.", progress = "You bring news from Kalimdor?", completion = "<Examines the orb with a worried expression>", sourceObjectiveStatus = "unverified-source-field" }
quests[78090] = { id = 78090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Second Opinion", description = "I'm not sure what to make of this orb, {name}. I think we will need the help of... a specialist.\n\nWe are aware of a warlock sect operating out of Stormwind. Officially we reject the presence of warlocks in the city. Unofficially, their knowledge can be of use when dealing with demonic forces.\n\nFind a representative of these warlocks, and seek their opinion on the orb.", sourceObjective = "Find the warlock sanctum within Stormwind and seek advice on the orb.", progress = "You're a long way from the cathedral, {class}. I hope you realize you have no authority here.", completion = "So the Silver Hand requires my aid? It will not come cheaply.", sourceObjectiveStatus = "unverified-source-field" }
quests[78091] = { id = 78091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earning Your Salt", description = "I will study the orb and tell you what I learn, but you must first do something for me.\n\nThe warlocks of the Blackrock clan use specially prepared salts to enhance their summoning rituals. Collect some from the orcs in Redridge.\n\nWhen you return, I will share with you the results of my studies.", sourceObjective = "Collect 14 Summoner's Salt from Blackrock Summoners in Redridge Mountains, then return to Ursula Deline in Stormwind.", progress = "<The warlock is studying the orb intently>", completion = "Ah... the salts. I had forgotten all about them.\n\nThis orb is unlike anything I have seen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78092] = { id = 78092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Must Be Destroyed", description = "The tendrils of sentience reaching out from this orb are too much for even an experienced warlock like myself to withstand for long. I am reluctant to admit this, {name}, but the orb must be destroyed.\n\nThe orb is nearly impervious, but it may be vulnerable to the weapon of a powerful demon lord. I have heard that such a blade is present in Ashenvale--at the site where the pit lord Mannoroth was destroyed.\n\nGather motes of the fallen demon's essence there, then shatter the orb upon the blade.", sourceObjective = "Gather 12 Motes of Mannoroth from demons in Ashenvale. Bring them along with the Orb of Althalaxx to the Spear of Mannoroth at Demon Fall Canyon.", progress = "<Your hair stands on end as infernal energies surround you>", completion = "<You raise the orb towards the spear>", sourceObjectiveStatus = "unverified-source-field" }
quests[78093] = { id = 78093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Delgren", description = "<The shattered remains of the orb lay at your feet. Delgren will want to see you have succeeded.>", sourceObjective = "Return the Orb Shards to Delgren.", progress = "Did you find a way to destroy the orb?", completion = "This is a relief, {name}. But whatever was watching Azeroth through that orb... I have a feeling they will not be happy it was destroyed.\n\nTake this as my thanks for your efforts. And... be careful.", sourceObjectiveStatus = "unverified-source-field" }
quests[78124] = { id = 78124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nar'thalas Almanac", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
