quests[79097] = { id = 79097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baxtan: On Destructive Magics", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79098] = { id = 79098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the Forest!", description = "This one is slain, but these infuriating alliance continue to fight... what is this charm?", sourceObjective = "Bring the Silverwing Sentinel Charm to Kazragore, Far Seer, at the Bonfire base in Ashenvale.", progress = "{name}, what news do you have from the front?", completion = "These Alliance dogs still prevent us from harvesting the resources needed for Orgrimmar. Continue to drive them out!\n\nThis Warsong battle drum will inspire you to fight them with greater determination. Lok'tar Ogar, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[79192] = { id = 79192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stepping Stones", description = "The note begins, \"Mission said they were both making deliveries for New Plague. Looks like simple apothecary accidents to me. Find my cozy spot in the mountains between The Barrens and Desolace if you want a safe place to talk.\"", sourceObjective = "You tear the note from the plank and read the scrawled writing.", completion = "Backcountry adventurers and mercenaries alike undoubtedly make camp here. The corner of a note flapping in the breeze catches your eye and you reach for it.", sourceObjectiveStatus = "unverified-source-field" }
quests[79229] = { id = 79229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highway Robbery", description = "The campsite before you is a grisly scene. Judging by the remains, the victims were two humans and a dwarf. Markings on the bones indicate a savage attack, but the looted supplies tell you this wasn't done by an animal. The wounds don't match centaur weaponry either.\n\nPerhaps an experienced scavenger of these lands would know what to make of this.", sourceObjective = "Find someone in Desolace who knows about the pillaged campsite.", completion = "Ah, so you found another one...", sourceObjectiveStatus = "unverified-source-field" }
quests[79235] = { id = 79235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Lam", description = "I've found a couple of scenes like you describe, {name}. Always camps of humans and dwarves. Rumor among the caravans is a group of Horde marauders did it. Seems likely given the victims, and how brutal the attacks were.\n\nApparently the bandits fled Desolace once an Alliance marshal got hot on their trail.\n\nIf you're looking to track one of 'em down, I'd check Booty Bay. Ports always have shady characters coming and going. You might catch one trying to get a boat to somewhere.", sourceObjective = "Find one of the Desolace marauders.", completion = "You need something? Make it quick.", sourceObjectiveStatus = "unverified-source-field" }
quests[79236] = { id = 79236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cherry for Your Thoughts?", description = "You with the marshal? No, you don't look like it.\n\nThe rumors you've heard are only half true. Yes, we were pillaging human and dwarven camps, but we weren't doing it for the Horde. We were privately employed.\n\nI'll tell you the whole story if you buy me some grog.", sourceObjective = "Bring a Cherry Grog to Tokal, in Booty Bay, to hear the rest of her story.", progress = "How's that drink coming?", completion = "Ah, that's the stuff. Now, where was I?", sourceObjectiveStatus = "unverified-source-field" }
quests[79242] = { id = 79242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Honor Among Thieves", description = "As I was saying...\n\nOur boss wasn't with the Horde. She was a night elf named Illari Duskfeather. She gave us intel on the camps, and even let us keep most of the loot. She only kept a few of the rarer finds.\n\nOnce the marshal was on our tail, though, she left us for dead. I don't know her motives, but I think we were set up as patsies.\n\nI'm not the vengeful type, but I won't stop someone else from hunting her down. If you're looking for her, she once mentioned a hideout on the coast of Arathi.", sourceObjective = "Find Illari Duskfeather on the coast of Arathi Highlands, and get access to her cache of stolen loot.", progress = "<Using Illari's key, you unlock the cache.>", completion = "<Inside of the cache, you find a small box, along with some coin.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79358] = { id = 79358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm, Earth, and Fire", description = "Floodin' the Thousand Needles is no small feat, {name}. If I hadn't felt the elements' outrage meself, I'd have never believed it. But here we are.\n\nThe quilboar aren't the first tae weaponize the elements irresponsibly, and they won't be the last. If we want to prepare our own counter-ritual, we'll need a better understanding of these twisted elements. Take this book. It details the many denizens of Azeroth and how they practice shamanism.\n\nIf you can learn from them, maybe we can find a solution.", sourceObjective = "Collect 5 Twisted Fire Totems, 5 Twisted Earth Totems, 5 Twisted Air Totems, and 5 Twisted Water Totems for Veyric Thunderhame in Arathi Highlands.", completion = "<Hmmph... the large tauren snorts as he reads the parchment.>\n\nOne things certain... whoever this note is from is right about their preparations going unseen. We've been too busy dealing with the centaur and harpies to send out wind riders to patrol the canyon and bluffs.\n\nYou have our gratitude for alerting us to this threat, but we might still need further assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[79360] = { id = 79360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Aid", description = "Now that you have mastered the elements, you have an obligation to them, and thus to all of Azeroth herself. We call to them for aid, we do not demand their power. It is time you return the favors granted to you. And I think I know how.\n\nThe quilboar twist the elements for their own ends, and seem to be extending their reach within these borders. Go into their kraul and put an end to whatever they scheme. These lands must be protected.", sourceObjective = "Defeat Charlga Razorflank in Razorfen Kraul and collect information on the quilboar's plans.", completion = "<You hand the note to Bath'rah who reads it over and gives a half hearted chuckle.>\n\nAh so it be true mon... I too have sensed much unrest in the elemental plane and dis must be one of the causes.\n\nTo flood all da Thousand Needles would take a great storm and many lives be lost.\n\nI t'ink I got just da t'ing for ya, but it won't come easy.", sourceObjectiveStatus = "unverified-source-field" }
quests[79361] = { id = 79361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm, Earth, and Fire", description = "So the quilboar mean to flood the Thousand Needles with their twisted shamanism, do they? It seems almost unimaginable, but you yourself have seen that these creatures are not to be taken lightly.\n\nI had wished to continue your training in earnest, but there is no time for that now. These lands are home to many different creatures, friend and foe alike, and none of them deserve such a fate. We must act.\n\nTake this tome. It was meant for study, but may now hold the key to dispersing this coming storm.", sourceObjective = "Collect 5 Twisted Fire Totems, 5 Twisted Earth Totems, 5 Twisted Air Totems, and 5 Twisted Water Totems for Prate Cloudseer in Thousand Needles.", progress = "Ah, you be gettin' a bit dusty out der?", completion = "Oh yes, yes. We be cookin' now.", sourceObjectiveStatus = "unverified-source-field" }
quests[79362] = { id = 79362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grant's Shield", description = "A shield left behind by the specter of Grant Valor, father of the Valor family and hero of Raven Hill.\n\nWith Grant's spirit still battling the undead, perhaps his unfinished business was to slay the scourge that injured him in the Raven Hill Cemetery. It is likely the one his mace is still imbedded in.", sourceObjective = "Find Grant's Mace on one of the skeletons in Raven Hill Cemetery then return to Sirra Von'Indie in Darkshire for more information.", progress = "You' legs be lookin' a wobbly der. De ground be shakin?", completion = "Let's get ready to rumble, ya?", sourceObjectiveStatus = "unverified-source-field" }
quests[79363] = { id = 79363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silvia's Sword", description = "A sword left by the spirit of Raven Hill's guard, Silvia Valor, who lived her life protecting civilians and their homes.\n\nWith Silvia's spirit still visiting farmsteads, perhaps her unfinished business was to route the defias who have taken up residence in Addle's Stead south of Raven Hill.", sourceObjective = "Defeat 7 Defias Night Blades and 7 Defias Enchanters in Addle's Stead then return to Sirra Von'Indi in Darkshire for more information.", progress = "Wade into any danger yet?", completion = "Shake dat sludge off, we almost done.", sourceObjectiveStatus = "unverified-source-field" }
quests[79364] = { id = 79364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes on the Sky", description = "The note you found says the Razormane have burrowed into the Thousand Needles for some sort of unseen ritual. Raging storms and rising tides...\n\nThe quilboar must be using some cruel sorcery they learned from Hirzek, a shaman who went to great lengths to twist the elements. If they plan to flood the canyon, this would require devastating elemental powers.\n\nWe are ill equipped to deal with this, but a powerful shaman like you must have an idea. Return to your allies and see if you can't find an answer.", sourceObjective = "Speak with Prate Cloudseer in Thousand Needles.", progress = "We need a larger vial and one of crystal clarity to contain these elements.", completion = "Knew I could count on you.", sourceObjectiveStatus = "unverified-source-field" }
quests[79365] = { id = 79365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With Wind Beneath Your Wings", description = "Here mon, a Squall-breakers Potion be what you need. Drink this to protect yourself against the elements of the storm, but remember it only goin' to last for a short while.\n\nNow go, return to your friends in need. There's nothing more I can do for you.", sourceObjective = "Return to Rau Cliffrunner in Thousand Needles at Freewind Post.\n\nProvided item:", completion = "Our wind riders have found something, but they have been unable to get close enough to assess the situation. Were you able to find anything that might help us?", sourceObjectiveStatus = "unverified-source-field" }
quests[79366] = { id = 79366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heed My Call", description = "Now that you have the twisted totems, we must wield them to summon forth the corrupted elementals the quilboar are calling upon. Defeat them to cleanse these lands and put an end to the Razormane's abominable ritual then report back to Rau Cliffrunner with your success.\n\nYou should begin your clensing at the steam pools to the west. That area is rich with each of the elements. But be careful, {name}. The quilboar will not sit idly while you interrupt their plans.", sourceObjective = "Use the Twisted Totems to put an end to the quilboar ritual.", progress = "What did you find?", completion = "The rumbling ground fell silent and in my heart I knew you had saved us. You have our gratitude, {name}.\n\nPlease accept one of these gifts as a token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[79442] = { id = 79442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tempest's Weapons", description = "Our people cannot thank you enough, but I have no real use for this eye. I have heard of an old shaman in the Alterac mountains that has an eye for storm elemental magic. Perhaps he may be able to craft something for you.", sourceObjective = "Deliver the Eye of the Tempest to Bath'rah the Windwatcher in Alterac Mountains.", progress = "Ahh! Looks like ye made it back in one piece there. Now tell me how did de potion do?\n\nWell 'tis a good thing I had faith in ya. Cuz dat potion be nothing but a mighty fine punch bru'dah. Much tastier than it be effective against those storms.\n\nNow, now... don't be angry wit me. All ya needed was a little encouragement. T'ings turned out how they was always meant to.\n\nBut since you's here... I did notice that mighty fine eye you be holdin...", completion = "Tell ya what. No more tricks, no more games. I got somet'in you'd be interested in.\n\nTrade me dat eye and I give you here this mighty fine rune that be ready to teach you new tricks.\n\nWhat ya say?", sourceObjectiveStatus = "unverified-source-field" }
quests[79482] = { id = 79482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Winter Veil Treats", description = "Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.\n\nWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains, and that's where our man went to look for it.\n\nSee if both are out there, safe and sound!", sourceObjective = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains.", completion = "Y-y-you can h-h-hear me!  Thank the b-b-bottom line!\n\nI'm not really a s-s-snowman - my n-n-name is Sacks, and I w-w-work for the Ironforge b-b-branch of Smokywood Pastures... I g-g-got sent out here to look for a m-m-missing package, when I was attacked by a c-c-creature I have never seen b-b-before!\n\nSo v-v-very cold...", sourceObjectiveStatus = "unverified-source-field" }
quests[79492] = { id = 79492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen the Reindeer", description = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Greatfather Winter's eight reindeer - and property of Smokywood Pastures.  We've received not one but TWO ransom letters from groups claiming to have Metzen.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen and return him to us!\n\nCheck out the ransom letters for clues, and sprinkle this reindeer dust on him - it will free him from any of his bonds!\n\nPlease, hurry!", sourceObjective = "Find Metzen the Reindeer. Use the notes provided to you for clues as to where he is being held.\n\nWhen you find Metzen, have the Pouch of Reindeer Dust in your possession so you can sprinkle some of the dust on him; this should free Metzen from his bonds of captivity.\n\nReturn the Pouch of Reindeer Dust to Wulmort Jinglepocket in Ironforge once Metzen is freed.", progress = "{name}!  Were the notes in the satchel I gave you enough information to locate Metzen?  I hate to think of that those cruel thugs might do to him... but there's no way we can afford to pay such an exorbitant ransom!", completion = "You did it!  Huzzah!\n\nMetzen flew back into Greatfather Winter's stables - yes Metzen can really fly - just a little while ago!  The dust worked like a charm; I knew it would.  You've saved the Feast of Winter Veil as well as Smokywood Pastures from disaster.  Thank you, {name}.\n\nListen... because of what you've done here, I want you to have this.  It's something VERY special; if you have a mount, I think you'll get a kick out of it.  Happy Winter Veil!", sourceObjectiveStatus = "unverified-source-field" }
quests[79495] = { id = 79495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen the Reindeer", description = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Great-father Winter's eight reindeer - and property of Smokywood Pastures.  We've received not one but TWO ransom letters from groups claiming to have Metzen.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen and return him to us!\n\nCheck out the ransom letters for clues, and sprinkle this reindeer dust on him - it will free him from any of his bonds!\n\nPlease, hurry!", sourceObjective = "Find Metzen the Reindeer. Use the notes provided to you for clues as to where he is being held.\n\nWhen you find Metzen, have the Pouch of Reindeer Dust in your possession so you can sprinkle some of the dust on him; this should free Metzen from his bonds of captivity.\n\nReturn the Pouch of Reindeer Dust to Kaymard Copperpinch in Orgrimmar once Metzen is freed.", progress = "{name}!  Did you find him?  Were the notes in the satchel I gave you enough information to locate Metzen?  I hate to think of that those cruel thugs might do to him... but there's no way we can afford to pay such an exorbitant ransom!", completion = "You did it!  Huzzah!\n\nMetzen flew back into Great-father Winter's stables - yes Metzen can really fly - just a little while ago!  The dust worked like a charm; I knew it would.  You've saved the Feast of Winter Veil as well as Smokywood Pastures from disaster.  Thank you, {name}.\n\nListen... because of what you've done here, I want you to have this.  It's something VERY special; if you have a mount, I think you'll get a kick out of it.  Happy Winter Veil!", sourceObjectiveStatus = "unverified-source-field" }
quests[79535] = { id = 79535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basilisks: Should Petrification be Feared?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79536] = { id = 79536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greater Friend of the Library", sourceObjective = "Thanks to your donations, the library is thriving.\n\nPlease, take this.", sourceObjectiveStatus = "unverified-source-field" }
quests[79624] = { id = 79624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anyone Can Cook", description = "The recipe appears to be for some sort of meat dish. It is written in a language you don't understand. Ogre is your best guess, given the source and subject matter.\n\nOgres aren't usually culinary types but, if you knew one with such an inclination, they could translate the recipe for you.", sourceObjective = "Find an ogre who can read the Illegible Recipe.", completion = "You have recipe? Skonk listening.", sourceObjectiveStatus = "unverified-source-field" }
quests[79637] = { id = 79637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ticking Present", sourceObjective = "Have a joyous Feast of Great-Winter from your friends at Smokeywood Pastures.", sourceObjectiveStatus = "unverified-source-field" }
quests[79731] = { id = 79731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Troll Scroll", description = "<The ancient glyphs resolve into words before your eyes.>\n\nWhen Zul'Kunda's fountain runs with the waters of the holy spring, the gods grant their blessing.", sourceObjective = "Solve the riddle of the scroll. Once you've done that, Hemet Nesingwary might like to hear the tale.", completion = "A magic fountain hidden in the jungle? What a story, {name}!\n\nThat gives me an idea for another chapter in my book! Let's see, where did I put that manuscript...", sourceObjectiveStatus = "unverified-source-field" }
quests[79947] = { id = 79947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geomancy: The Stone-Cold Truth", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79948] = { id = 79948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defensive Magics 101", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79949] = { id = 79949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Web of Lies: Debunking Myths and Legends", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
