quests[79952] = { id = 79952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RwlRwlRwlRwl!", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79974] = { id = 79974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wet Job", description = "\"Always like to keep a reserve stash nearby in the off chance I've got to flee in a hurry.\n\nThe face of this mountainside is so beautiful you might say it was carved from the waterfalls of time. \nThat's the eagles nest, that's what you're looking for.\"", sourceObjective = "Dusting off a messenger bag emerging from the soil, you find a parchment nestled among the supplies.", completion = "Dwarven Engineering, always a marvel.", sourceObjectiveStatus = "unverified-source-field" }
quests[79975] = { id = 79975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eagle's Fist", description = "<You find a carefully folded letter inside of the toolbox.>\n\n\"From here, with the right tools, you call the shots. Great place to launch a parachute glider.\n\nMy loyalty to the Eagle and Fist requires distance in order to serve them best. This barricade has had better days, like the Old Kingdoms it once defended, but I'll never abandon it.\"", sourceObjective = "Water spray dampens the air, the view is incredible.", completion = "A campfire is newly fed with wood, but signs of a quick departure are evident.", sourceObjectiveStatus = "unverified-source-field" }
quests[79976] = { id = 79976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Must Be The Place", description = "\"So, I've decided to take my work back underground. To stop it falling into the wrong hands.\"\n\n<The paper is torn just large enough to fit the message. You aren't sure if these are the last words you'll read from the author, or if they're a clue to the next hideout. An inadequately secured sleeping bag is unrolling itself onto your feet...>", sourceObjective = "Whoever was here, you just missed them.", completion = "Heavy canvas is rolled over assorted equipment. You help yourself to the pack.", sourceObjectiveStatus = "unverified-source-field" }
quests[79980] = { id = 79980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scramble", description = "\"Not so bad, eh? Since you're reading this, it means my stash is still there. Take a hundred paces due north and don't break your ankles going down the steep cliffside. There should be enough to keep you going.\"", sourceObjective = "Find what awaits you.", completion = "You pull a messenger bag out of the ground. Stuffed in with the supplies is a dirty parchment.", sourceObjectiveStatus = "unverified-source-field" }
quests[80001] = { id = 80001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekindle", progress = "An extinguished fire pit. The wood is even dry enough to catch a flame.", completion = "You put your scout skills to work." }
quests[81730] = { id = 81730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission I: Defeat Worgen", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion in the Rotting Orchard. Defeat worgen there and return to me.", sourceObjective = "Defeat 10 Nightmare Runners and 10 Nightmare Weavers in the Duskwood Nightmare Incursion in the Rotting Orchard and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81731] = { id = 81731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission II: Defeat Ogres", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Vul'gol Ogre Mound. Defeat ogres there and return to me.", sourceObjective = "Defeat 3 Deranged Ogres and 3 Demented Fire Weavers in the Duskwood Nightmare Incursion at the Vul'gol Ogre Mound and return to Field Captain Palandar.", progress = "You've dealt with the ogres?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81732] = { id = 81732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission III: Defeat Dragonkin", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Yorgen Farmstead. Defeat dragonkin there and return to me.", sourceObjective = "Defeat 3 Wyrmkin Terrorwalkers and 10 Nightterror Whelps in the Duskwood Nightmare Incursion at the Yorgen Farmstead and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81733] = { id = 81733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission IV: Ogre Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Vul'gol Ogre Mound. Retrieve an intelligence report from Dreamwarden Thalinar there and return to me.", sourceObjective = "Gather intelligence from Dreamwarden Thalinar in the Duskwood Nightmare Incursion deep inside the Vul'gol Ogre Mound and return to Field Captain Palandar.", progress = "You have the report?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81734] = { id = 81734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission V: Worgen Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Rotting Orchard. Retrieve an intelligence report from Dreamwarden Dorilar there and return to me.", sourceObjective = "Gather intelligence from Dreamwarden Dorilar in the Duskwood Nightmare Incursion in the barn at the Rotting Orchard and return to Field Captain Palandar.", progress = "You have the report?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
