quests[82208] = { id = 82208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greater Friend of the Library", sourceObjective = "Thanks to your donations, the library is thriving.\n\nPlease, take this.", sourceObjectiveStatus = "unverified-source-field" }
