quests[91906] = { id = 91906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sealed Crate" }
quests[91920] = { id = 91920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Eyes", description = "I wouldn't dare to question the effectiveness of Apothecary Renferrel's formulae, however I would be lying if I said that the potion made any noticeable difference.\n\nAlong the shore of Lake Lordamere are a swarm of murlocs, and of note, murlocs have eyes. I suspect the apothecary's willingness to try new things is suppressed by his recent obsession with hearts. Bring him a few.\n\nIf my choice is to inevitably die a second death or have Renferrel kill me for questioning his methods, I choose the latter.", sourceObjective = "Gather 3 murloc eyes and bring them to Apothecary Renferrel at the Sepulcher.", progress = "Oh. You're back?", completion = "The potion didn't work? Of course it didn't work. You brought me insufficient hearts. The recipe clearly calls for six. You brought three.\n\nHowever, I confess I hadn't considered applications for murloc parts until now...\n\n<Renferrel takes the eyes.>\n\nI can afford to sacrifice a few of my own hearts to get your Deathstalker's strength back.", sourceObjectiveStatus = "unverified-source-field" }
quests[91921] = { id = 91921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Quinn (Again)", description = "Here is the new potion to aid in Quinn's recovery, made with love extracted from six whole hearts.\n\nNow, please excuse me before your presence necessitates more paperwork.", sourceObjective = "Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher.", progress = "You return! I was beginning to come to terms with devolving into a ghoul.", completion = "<Quinn takes the potion and drinks it.>\n\nYes, I can feel it working.  I will soon be able to travel.\n\nYou have done me a great favor, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[92109] = { id = 92109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My First Alchemy Set", description = "Erm... 'Ello, <mister/miss>. I'm not supposed to talk to strangers, but... Hey, what are those shiny bottles sticking out of your backpack for? Are you an alchemist? That's so cool!\n\nWhen I grow up, I want to be an alchemist too. Daddy won't let me play with any of his herbs; too dangerous, he says.\n\nWell, I want to start learning now. Could you maybe get some supplies for me, pretty please?", sourceObjective = "Gather 5 Empty Vials, 5 Silverleaf, and 5 Peacebloom to the young, aspiring alchemist inside the barn of Moonbrook in Westfall.", progress = "'Ello again! Did you bring back alchemy stuff?", completion = "Oh my gosh! Look at these! Did you pick the herbs yourself?\n\nWow, thanks mister, I am going to see what I can make with these right now! Do you want to watch?", sourceObjectiveStatus = "unverified-source-field" }
quests[92110] = { id = 92110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My First Real Potion", description = "Wow, my very first potion! Did you know that mixing those two herbs together would change the potion to a bright red color when you first started?\n\nThat was fun, but mixing a few flowers doesn't seem like the kind of alchemy Daddy does. He uses other ingredients too.\n\nI don't know what else to use, so let's try the first thing that comes to mind! Let's see... maybe murloc eyes? That sounds so gross, but I bet something will happen.", sourceObjective = "Gather 3 Murloc Eyes for the young, aspiring alchemist inside the barn of Moonbrook in Westfall.", progress = "Don't worry about me, I'm a big girl. I can take care of myself. Just don't tell anyone I am hiding here, it's our little secret.", completion = "You brought me murloc eyes! I am so excited for my first REAL potion I can't breathe!\n\nI snuck out and grabbed a few more herbs while you were away and found some empty vials downstairs. Um... you can do the mixing this time.\n\n<The child watches enthusiastically you mix the ingredients, but her nose crumples as you add the eyes. The concoction takes on a sickly orange in mere seconds.>\n\nWow! See, I was right. I wouldn't drink that, but here's my recipe if you wanted to make more. Come back sometime!", sourceObjectiveStatus = "unverified-source-field" }
quests[92124] = { id = 92124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Book Inventory", description = "We need to take stock of how many books are missing!\n\nGo talk to my useless assistant, Daniel. He can do a quick inventory and let us know how serious the problem is.\n\nHe's obsessed with the various trade professions in Elwynn Forest. The boy keeps focusing on those instead of his important work helping me.\n\nDon't let him prattle on about tradeskills, and find out what's happened to my books!", sourceObjective = "Speak to Daniel, Brother Paxton's assistant in the library.", completion = "Yah, I overheard. I warned Brother Paxton three times about the kobolds tunneling under the abbey.\n\nIt looks like the kobolds have taken a lot of books. There are whole bookshelves emptied out. You should probably see what Brother Paxton wants you to do about it.\n\nWhile you're here, can I talk to you about tradeskills? I'd be happy to answer any questions you have, or point you toward the local trainers.", sourceObjectiveStatus = "unverified-source-field" }
quests[92401] = { id = 92401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Frightened Request", description = "It's my husband Edward...\n\nHe has not returned from his weekly journey to the graveyard in the Lordaeron ruins. Our son was lost when Arthas razed the city, and my dear Edward is still filled with guilt and sorrow that we never found his body. I've tried to warn him against searching those overrun ruins, but he refuses to give up. I try not worry, but it's been days.\n\nThere are things there I cannot contend with but if you are willing, I need to know the fate of my husband.", sourceObjective = "Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron.", completion = "What I asked of you was not fair, nor would it have been unjust for you to simply walk away. Thank you stranger. I am unable to repay you in kind but I hope one of these is acceptable.\n\nI hope our paths cross again without such sorrow.", sourceObjectiveStatus = "unverified-source-field" }
quests[92415] = { id = 92415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remember That I Love You", description = "<A torn and stained bundle of parchment has barely survived the undead trodden grounds of the graveyard. It mentions a missing child of the Heartweaver family. Perhaps the orphan matron in Stormwind City will know more.>", sourceObjective = "Bring the Blood-Stained Letter to Orphan Matron Nightingale in Stormwind City.", progress = "What is it, {name}? What are you looking for?", completion = "Heartweaver? Heartweaver...\n\nOh! Little Jeremy Heartweaver. He was brought in years ago after the attack on Lordaeron. Lost both of his parents in the attack, poor thing.\n\nHe was actually adopted not too long ago by a sweet woman out in Duskwood.", sourceObjectiveStatus = "unverified-source-field" }
quests[92421] = { id = 92421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light's Justice", description = "As a paladin of the Forsaken, it is my duty to exact the will of our Dark Lady while tending to our people's needs. We are fortunate with an opportunity to accomplish both.\n\nAbove the Undercity, the scourge still roam unchecked in great numbers. Our forces dwindle trying to reclaim our land, and decaying flesh cannot be reknit. Not without replacements.\n\nWould that our glorious captain Garek Bandarion still be with us, I know what he would wish. To finish what he started and heal our kin. For Lordaeron!", sourceObjective = "Collect 25 Intact Limbs within The Ruins of Lordaeron for Morbin Lightbane in the Undercity.", progress = "What remains of the invading scourge? Have you managed to find suitable replacement parts?", completion = "Let those who fall from the Banshee Queen's grace meet our justice!\n\nWith these parts, our brothers and sisters have hope to see another day. You do Captain Bandarion proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[92422] = { id = 92422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of Rath'mael", description = "Reports have come in from the Lordamere Overlook deep within the Ruins of Lordaeron. An unholy fog has taken over the streets and graveyard, affording the scourge up there some measure of stealth. \n\nOur scouts indicate they're being conjured by a new power within their ranks, a necromancer known as Rath'mael. We do not have the luxury of waiting this one out, {name}.\n\nIf you have allies, summon them and their aid to the Forsaken. Drive this creature out of our lands.", sourceObjective = "Kill Rath'mael in the Ruins of Lordaeron for Deathguard Kristof in Brill.", completion = "While I have no doubt something of his kind will be replaced, we can only hope their ranks thin in the meantime.\n\nThank you {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[92432] = { id = 92432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Alarming Request", description = "I bring ill tidings from Dalaran. Something has disrupted our ley lines, causing erratic and destructive behavior from our constructs in the city.\n\nWe know not yet what is causing this mayhem. The high council has ordered us to keep this matter private so as to not bring shame to our order. But we cannot keep up this charade forever. The city is being overrun as we speak!\n\nArchmage Modera has dispatched me to solicit outside aid. Seek her image out near Dalaran beside Lordamere Lake.", sourceObjective = "Report to the Image of Archmage Modera near the City of Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[92434] = { id = 92434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood in the Streets", description = "Whatever caused Dalaran's barrier to lower has left the city in turmoil. With you having dealt with their patrols, there is no better time than now to make our way inside and discover their secrets.\n\nTake the key you found at the internment camp and seek out their sewers along the northern border of the city. With luck, those mages had no reason to put a ward over such a... disagreeable point of entry.", sourceObjective = "Find a way into Dalaran along the Lordamere Lake.", sourceObjectiveStatus = "unverified-source-field" }
quests[92454] = { id = 92454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Dalia Windbreeze in Thendal Grove.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!You will be able to choose one of these rewards:", sourceObjective = "Bring the Thendal Grove Gift Voucher to Dalia Windbreeze.", sourceObjectiveStatus = "unverified-source-field" }
quests[92456] = { id = 92456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Green Sample", description = "If you're going to bother me you can at least make yourself useful. I have an errand I need run.\n\nFor a city of mages, Dalaran has a surprising interest in botany. The Kirin Tor keep to themselves, but I would love a sample of their mana-infused vegetation.\n\nYou're clearly someone who is comfortable being where people don't want you, maybe you could find a way into the city. If you do, bring me back whatever is growing in their central garden.You will be able to choose one of these rewards:", sourceObjective = "Collect a Fel Infused Blossom from the City of Dalaran for Shylamiir in Stormwind City.", sourceObjectiveStatus = "unverified-source-field" }
quests[92457] = { id = 92457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starving Arcane", description = "The breach has affected many of our factotums and enchantments throughout the city, including many that are seeing to our defenses. This fragmented arcane energy has spoken to rogue elementals who seek to saturate themselves in this free flowing magic.\n\nWhile we are busy tending to the wards and other major incidents, it would be a favor to the Kirin Tor if you could cull this elemental throng.You will be able to choose one of these rewards:", sourceObjective = "Defeat 8 Seeking Remnants, 8 Saturated Remnants, and 8 Mana Echoes inside the City of Dalaran for Archmage Modera outside of Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[92458] = { id = 92458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Disruption", description = "Whatever disturbed the ley lines, it started at the top of the Violet Citadel. A thunderous crash rang out from the parlors above, and now we are overrun with rampant arcane power. It's taking all we have just to keep the wards in place.\n\nWe cannot afford to stall any longer. We need help.\n\nThe Kirin Tor are busy inside, but you will still need a less public approach to gain entry. Take this key and meet me in the citadel once you've made your way into the city. We must put an end to this disruption.You will be able to choose one of these rewards:", sourceObjective = "Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[92460] = { id = 92460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coming of Age", description = "Look at you, bright eyed and ready for adventure! We've been awaiting your arrival and anticipating your much needed help here in Thendal Village. I imagine you are brimming with both nerves and excitement for what is to come. After all, you only get to come of age once in a lifetime.\n\n<Ailee smiles kindly.>\n\nGo, seek out our village leader Rorian the Dayseeker at the entrance to the greatfather tree just west of here. He will get you started on your journey.", sourceObjective = "Speak with Rorian the Dayseeker in Thendal Grove.", completion = "Gale's greetings, {name}. I am honored to bestow your coming of age relic today as you are recognized for the potential you bring to the shen'dorei. Our people have faced great hardship and persecution in our complex history.\n\nToday you are given this relic which is one of many held by those before you. Someday when your ashes are scattered to the winds it will pass to another to continue our tradition.\n\nAs you take this relic with you know that the winds of home will be with you wherever you travel.", sourceObjectiveStatus = "unverified-source-field" }
quests[92461] = { id = 92461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harmony in Balance", description = "We live in times of great uncertainty for our people. We face unprecedented challenges that may require bold solutions, but we also must contend with the ordinary and mundane here in Thendal Grove. Take, for example, the recent unsustainable rise in the vuldren population.\n\nThe vuldren are a vital part of our ecosystem. However, imbalances must be corrected to maintain the delicate harmony that all creatures in Thendal Grove share.\n\nHead east and cull some of the vuldren there.", sourceObjective = "Slay 8 Vuldren Juveniles in Thendal Grove.", completion = "Thank you for your service to Zephras, young {class}.\n\nThe vuldren are typically quite docile, but the animals that call Zephras home can sense when the magic on the winds is out of balance, which can lead to dangerous and unpredictable behavior if left unchecked.", sourceObjectiveStatus = "unverified-source-field" }
quests[92462] = { id = 92462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infestation Investigation", description = "One of our rangers recently reported an infestation of cirrusflies here in Thendal Grove. \n\nCirrusflies can be dangerous if the swarm is allowed to grow too large, so please head to the eastern end of the Grove and exterminate as many as you can.", sourceObjective = "Slay 8 Pesky Cirrusflies in Thendal Grove.", progress = "Such pests cannot be allowed to find root in our peaceful grove. An infestation can quickly grow dangerous if left unchecked.", completion = "Judging by the amount of bug entrails covering you, this must be quite the infestation.", sourceObjectiveStatus = "unverified-source-field" }
quests[92463] = { id = 92463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cirrusfly Queen", description = "If the forest is as thick with these insects as it sounds, simply killing the workers won't be enough.\n\nGo deeper into the forest and find the queen. She'll be close to the hive and surrounded by bigger and more aggressive soldiers, so be careful.\n\nPut her down and return here when it's done. That'll be one less problem to think about around here.", sourceObjective = "Destroy the Cirrusfly Queen in Thendal Grove.", progress = "Cirrusflies aren't to be underestimated. They might not seem dangerous, but you have to watch out for the bigger ones. The bigger they are, the meaner!", completion = "Excellent work, {name}. You'd make a fine ranger if this whole \"adventurer\" thing doesn't work out for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[92464] = { id = 92464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Unrest", description = "Ever since our elemental benefactors left us, it seems that we are simply moving from one unrest to another. The problem we face now is that the manifestations of the winds near the standing stones to the northeast are agitated.\n\nNot truly self-aware like the sentient wind spirits that once lived here, these simple sprites respond in kind to forces, emotions, and intentions of the creatures around them. \n\nMy apprentice Yala Windwatcher went to observe them. Seek her out and discover what she's learned.", sourceObjective = "Speak to the Yala Windwatcher in Thendal Grove.", completion = "Rorian sent you? Good. I could use your aid.", sourceObjectiveStatus = "unverified-source-field" }
quests[92465] = { id = 92465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agitators", description = "The Al'Aketh cult is a blight upon this island. These cultists are surely the ones responsible for agitating the simple wind sprites that reside here and turning them violent.\n\nRegrettably, we'll need to disperse these roiling winds here before they harm someone. We also need to send a clear message to the cult that they are not welcome in the grove.\n\nWill you lend me your aid, {class}?", sourceObjective = "Slay 6 Roiling Winds and 7 Al'Aketh Converts in Thendal Grove.", progress = "Is it done?", completion = "It pains me to shed shen'dorei blood here in the grove, but we do what we must.", sourceObjectiveStatus = "unverified-source-field" }
quests[92466] = { id = 92466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "While we owe much of our prosperity to the elements of wind, the path we walk requires that we obey the call of all four of the primary elements and undertake a trial for each. Before you begin your first trial in earnest however, you must prove the strength of your resolve.\n\nTravel to the standing stones to the east. A force of Al'Aketh converts has been spotted there and they must be driven off. Confront the cultists there and bring me one of their signets as proof of your deeds.", sourceObjective = "Bring a Signet of Akir to Windshaper Boro.", progress = "The Al'Aketh cult represents the most direct and urgent danger to our homeland. Their increasingly extremist actions have destabilized our society and damaged our already-weakened connection to the spirits of the four winds. The elements demand action to prove our resilience and resolve, which are traits that are endemic to the domain of the element of earth.", completion = "You have returned and brought what I have requested and thus your grit and determination are unquestionable. You are ready for the next step, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[92467] = { id = 92467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the strong willed to see the elements as no one else can. Your spirit will be connected to the element the sapta was created for, and only a select few shaman know the recipe.\n\nThe sapta is always drunk in a sacred place, and never anywhere else--remember that.\n\nSeek out the Rise of Spirits up the pass northeast of here. Drink your sapta there, and... well, you will see what you need see.", sourceObjective = "Find the Rise of Spirits and drink the Earth Sapta.\n\nProvided item:", completion = "Ah... {name}... child of the four winds... You seek understanding. You seek answers. Why have the winds left you? How may you get them back? These are answers I cannot provide, for I do not know the motives or movements of the winds.\n\nI can, however, teach you much of the earth. Its strength, its resolve. Even here, high in this endless sea of clouds, you are still a creature of the earth. If you hope to find the strength to speak to the spirits of the four winds once more, this is the path you must walk.", sourceObjectiveStatus = "unverified-source-field" }
quests[92468] = { id = 92468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "Take this Rough Quartz from me and bring it to the one you call Windshaper Boro as proof of our meeting. He will craft a totem for you, and this shard will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast many others.\n\nBe patient, {name}. Remain strong. And seek wisdom. This is what the elements ask of you. In the end, you shall become one with the earth--respect it as it shall respect you.", sourceObjective = "Bring the Rough Quartz to Windshaper Boros in Thendal Grove.", progress = "As you will come to learn, the path we walk is not as simple as it may seem. While we seek to find the voice needed to speak with the spirits of the winds, the winds are but one of the elemental forces of this world. Only through understanding, and--we hope--mastery of all four elements will we regain our voice to again sing the songs of the wind.", completion = "Good!\n\nThe totem I will craft for you is more than a symbol of your status among {class}--it has abilities beyond that. One use of the totem is as a focus for spells. Those spells are tied to the earth, and as you earn greater and greater wisdom, more of the earth's abilities will be made accessible to you.\n\nThe trainers will know when you are ready for greater knowledge.\n\nBut for now, take this earth totem...", sourceObjectiveStatus = "unverified-source-field" }
quests[92469] = { id = 92469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Rorian", description = "You've done enough here, {class}. I'll stay and clean up any stragglers down there.\n\nHead back to the Village and tell Rorian about the cult's presence. He will not be pleased.", sourceObjective = "Bring word of the Al'Aketh to Rorian the Dayseeker in Thendal Grove.", completion = "This is most troubling, but unfortunately unsurprising. We've been aware of the cult's movements for some time, but we've been content to watch from afar. Their agitation of the wind spirits near the standing stones is a clear escalation on their part.\n\nYou've performed a difficult but necessary service for Thendal Grove, {name}. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[92470] = { id = 92470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foul Matriarch", description = "Rorian informed you that I've been watching you. I now offer you a test of resolve. However, be warned--it will send you into great danger.\n\nGo to the caves to the south. Thin out the ursera's numbers there, and find their matriarch, one the rangers call \"Urs'anah\". Put her down and bring me proof of her demise. Once you have done that, you will have taken an important step on your path.", sourceObjective = "Slay 8 Ursera Scavengers and collect the head of the den mother, Urs'anah in Thendal Grove.", progress = "What I ask of you is not easy, but you must be prepared for much greater challenges if you are to survive long enough to be of service to Zephras Isle.", completion = "Very well done. You've felled beasts and laid low cultist interlopers. You have shown great promise but your path must soon take you beyond the relative safety of Thendal Village.", sourceObjectiveStatus = "unverified-source-field" }
quests[92471] = { id = 92471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aetheen of the Gales", description = "You may not realize this but everything you've done has been a trial of sorts. A test for what is to come for you. It's a big island out there, and Zephras needs spirited young adventurers such as yourself if we are to survive the trials our people face.\n\nThe one called Aetheen of the Gales is one of the leaders of our people here on Zephras Isle, and she has been watching you. She has a task that you must complete. Speak with her to learn more.", sourceObjective = "Speak with Aetheen of the Gales in Thendal Grove.", completion = "Rorian has told me much of you. I am likely unknown to you, but I am a member of the Council of Elders here on Zephras Isle. I've come to read the flow of the winds here in Thendal Grove. I'm also here to assess young shen'dorei such as yourself that are coming of age.\n\nSo tell me, are you ready to take your next step? Are you ready to serve Zephras Isle?", sourceObjectiveStatus = "unverified-source-field" }
quests[92472] = { id = 92472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Next Step", description = "One of the most pervasive threats on Zephras Isle is the Al'Aketh Cult. They are religious zealots devoted to the worship of the supposed elemental ruler of Skywall, Al'Akir the Windlord. They are brutal, single minded, and their power and ambitions are growing more deadly by the day.\n\nYour path will soon take you to Shen'dar Village to the south. Present yourself to Constable Aonda when you arrive. The cult threatens Shen'dar and they are in need of aid. Tell Aonda that I sent you.", sourceObjective = "Report to Constable Aonda in Shen'dar Village.", completion = "Aetheen sent you, then? I'll confess, you don't look like much to me, but Shen'dar Village won't turn down willing aid, much less aid sent from Elder Aetheen herself.", sourceObjectiveStatus = "unverified-source-field" }
quests[92473] = { id = 92473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Encroachment", description = "The ursera den to the southwest is rapidly becoming a problem. Just last week the rangers had to kill an adolescent ursera who wandered too close to the village and attempted to attack a boy playing near the base of the elder tree in the center of the village.\n\nWe were fortunate that the boy escaped with his life. Hunger and desperation makes these beasts too dangerous to be left unchecked. Go south and put the scrawniest among the ursera down. Bring me their claws as proof when it is done.", sourceObjective = "Collect 6 Scrawny Ursera Claws from Scrawny Ursera in Thendal Grove.", progress = "The ursera have grown far more aggressive of late. I wonder what has changed to cause this shift in behavior?", completion = "Well done, {class}. The Rangers of the Grove are in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[92474] = { id = 92474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falling With Style", description = "Well hello there, {name}! Want to play a game?\n\nAll you've got to do is step up on that ledge... then jump! Use your innate ability to walk on the air to slow your fall and see how far forward you can float.\n\nThe rules are made up and the points don't matter, but you get bonus points if you can land right in front of Rorian the Dayseeker and startle him! He won't like it but I'll certainly get a good laugh if you can get him all worked up! Hah!", sourceObjective = "Jump from the top of the watchtower in Thendal Grove and use your Walk on Air ability to slow your fall.", progress = "Using your ability to walk on air can get you out of--and, well... into--all kinds of trouble!", completion = "How many times do I need to tell Myriaal not to encourage others to make reckless usage of our skyborne gifts!\n\nThat being said, I suppose that a little bit of practice in the relative safety of the village is... acceptable.\n\nIn the future I'd simply suggest you to use your ability judiciously. You do not want to exhaust your magic thoughtlessly and then not be able to use it when you truly need it.", sourceObjectiveStatus = "unverified-source-field" }
quests[92479] = { id = 92479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scribbled Letter", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, {name}. It appears to be a letter sealed with the mark of Tordrin Stemblade, our local hunter trainer. Take a moment to read it before you go about any other business here in the Abbey.", sourceObjective = "Read the Scribbled Letter and speak to Tordrin Stemblade in Northshire Abbey.", progress = "Ah, ye got me letter, {name}... good.\n\nTime was when ye'd not catch a {race} dead wit' a bow in their hand--no more, I guess. It's good for Stormwind, but bad for the kobolds and man eatin' beasts in the area.", completion = "Get yerself squared away, learn the lay o' the land, and come back to me whenever you need training. I'll be here night or day.\n\nThis land is grown' more dangerous, and as ye meet other folk, I think ye'll find they all have problems they could use some help with--help a skilled {class} can give 'em. Good luck.", sourceObjectiveStatus = "unverified-source-field" }
quests[92481] = { id = 92481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Student of the Arcane", description = "While you were away dealing with our vuldren problem, our resident mage trainer--Dorii Brightwhisper--left this recall crystal for you. It contains some sort of message for you, so give it a look. Afterwards, you can find Dorii in the structure just behind me.", sourceObjective = "Examine the Glowing Recall Crystal, then speak with Dorii Brightwhisper in Thendal Grove.", progress = "Greetings, {name}. I'm pleased to have the privilege of furthering your magical studies.", completion = "Let me have a look at you. Yes, I believe you will make a fine young {class}. The power of the arcane has waned amongst our people, but there are those who would seek to rediscover much of what we've lost in the millennia we've spent here amongst the clouds. I am sure that you will lead the charge in this never ending search for arcane knowledge, and ultimately make us proud.\n\nSpeak with me again if you wish to take your next steps.", sourceObjectiveStatus = "unverified-source-field" }
quests[92482] = { id = 92482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way of the Hunter", description = "While you were away dealing with our vuldren problem, our resident hunter trainer--Tai'ree Farsight--left this note for you. You can find her just over yonder near the center of the village. Read the note then seek her out.", sourceObjective = "Read the Scribbled Note and then speak with Tai'ree Farsight in Thendal Grove.", progress = "<Tai'ree nods at you curtly.>", completion = "The way of the {class} is fraught with danger, and only those with the keenest senses and quickest reflexes can thrive in the wilds. I look at you and I am reminded of myself when I stood before my mentor, so many years ago. I believe that you have what it takes, but in the end that is up to you alone.\n\nSpeak with me again if you wish to take your next steps.", sourceObjectiveStatus = "unverified-source-field" }
quests[92483] = { id = 92483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At Home in the Shadows", description = "While you were away dealing with our vuldren problem, our resident rogue trainer--Akeri Duskblade--has requested to speak with you. He left this note, so read that first, then seek him out inside the watchtower, here in the village.\n\nHe's a shady fellow, but then again, so are you. I think you'll get along well.", sourceObjective = "Read the Simple Note then speak with Akeri Duskblade within the watchtower in Thendal Grove.", progress = "<Akeri eyes you suspiciously.>", completion = "I almost did not hear you approach me, young {class}.\n\nAlmost.\n\nAlmost won't be good enough when you leave Thendal Grove. You must be a slender blade, silent and steady. Ever vigilant and ever mindful of your surroundings. You might have what it takes to survive the dangers of Zephras. You also might end up with your throat slit in a ditch. Ultimately that's entirely up to you.\n\nSpeak with me again if you wish to take your next steps.", sourceObjectiveStatus = "unverified-source-field" }
quests[92484] = { id = 92484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Embracing the Elements", description = "While you were away dealing with our vuldren problem, our resident Shaman trainer--Windshaper Boro--left this recall crystal for you. Please examine it, then speak with Boro just over yonder near the center of the village.", sourceObjective = "Examine the Humming Recall Crystal then speak with Windshaper Boro in Thendal Grove.", progress = "Winds guide you, {name}.", completion = "Can you hear it? The whispers of the winds? Doubtful, considering that the spirits stopped speaking with us when they left us those years ago. \n\nThose among us who would seek audience with the spirits of the four winds once more hone our understanding of the elements and the natural world, dearly hoping to reestablish the dialogue that was so abruptly ended. \n\nWould you walk this path and master the elements?\n\nSpeak with me again if you wish to take your next steps and I will train you.", sourceObjectiveStatus = "unverified-source-field" }
quests[92485] = { id = 92485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Student of Nature", description = "While you were away dealing with our vuldren problem, our resident druid trainer--Xyton Silverwind--left this note for you. Read it as soon as you can, and then seek out Silverwind on the ground floor of this great tree just behind me.\n\nHeed his words and his counsel, he can teach you much.", sourceObjective = "Read the Folded Parchment then speak with Xyton Silverwind in Thendal Grove.", progress = "Greetings, I am Xyton Silverwind, keeper of druidic lore.", completion = "The flora and fauna of Zephras Isle represent a rich tapestry of vibrant life. The ecosystem requires constant balance to maintain the harmony of nature, and we druids are the keepers of that balance. I see much potential in you, but this path is not an easy one, and you will need guidance as you grow in strength as a student of the fang, the claw, the feather, and the branch. \n\nSpeak with me again if you wish to take your next steps.", sourceObjectiveStatus = "unverified-source-field" }
quests[92489] = { id = 92489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Overwhelming", description = "The Kirin Tor have long been allies of the Alliance. With the destruction of their city at the hands of the arch demon Archimonde, the once proud city of mages has now become reclusive and distrusting of outsiders.\n\nIn recent years they have begun reconstruction efforts to bring the city of Dalaran back to its former glory. However, reports show they are struggling to contain an outbreak of wayward arcane energies.\n\nWe must help them disperse these attacks lest we lose one of our most powerful allies.You will be able to choose one of these rewards:", sourceObjective = "Slay the Mana Elemental in the City of Dalaran for High Sorcerer Andromath in Stormwind City.", sourceObjectiveStatus = "unverified-source-field" }
quests[92514] = { id = 92514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Shen'dar Village", description = "You've got that \"Windshaper\" air about you. Something about how I can feel a tiny bit of static on my skin when near someone spirit-touched that gives it away. Before I properly put you to work around here, you should check in with our resident Windshaper elder, Illaya Amberwind. She's just outside, near the center of town.\n\nOh, and check in with Coriella Calmbreeze as well, she runs the local inn and can provide lodging and supplies, should you need them.", sourceObjective = "Speak with Illaya Amberwind and Coriella Calmbreeze in Shen'dar Village.", completion = "Checked in with Illaya then? Great. Lots of tension between the High Order and the Windshapers these days, but they keep things civil here in Shen'dar. Everyone here is well aware that we've got bigger problems than their quibbles.\n\nNow that that's done, you look like someone who might be looking for something to do with their hands and I've got a bandit problem that I was hoping you could help me with.", sourceObjectiveStatus = "unverified-source-field" }
quests[92515] = { id = 92515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Problem With Prideclaws", description = "As if bandits and mad cultists weren't enough, the hills are thick with prideclaws as well right now. They are starting to encroach on the village borders and growing bolder by the day. It's only a matter of time before someone's pet or child is taken. It would be a mercy for us to cull their numbers now rather than after some tragedy occurs.\n\nBring me a dozen or so of their pelts. I can turn them into all sorts of goods that will be of aid to the village.", sourceObjective = "Collect 10 Prideclaw Pelts from the Prideclaws in Shen'dar Highlands.", progress = "If you ask me, I think Prideclaws are actually kind of cute. From a safe distance... and while standing behind someone holding a sword, of course.", completion = "I didn't say it wouldn't be a dirty job, did I?", sourceObjectiveStatus = "unverified-source-field" }
quests[92516] = { id = 92516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hippogryph Harrassment", description = "A flock of Hippogryph have recently established nesting grounds southeast of Shen'dar Village and they've been wreaking havoc on travelers on the road. I need someone to head down there and thin them out for us.", sourceObjective = "Slay 8 Hippogryph Youths, 6 Hippogryph Protectors and a Hippogryph Matriarch in the Shen'dar Highlands.", progress = "Hippogryphs are very proud creatures. It's probably the noise from the wagon trains that rile them up and cause them to attack. Whatever the reason for the attacks, dead caravaneers aren't something that we can ignore.", completion = "Well done, and quickly too. Not too bad at all.", sourceObjectiveStatus = "unverified-source-field" }
quests[92517] = { id = 92517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Criminal Element", description = "There's a cave not far to the north, hidden behind a waterfall. It's well known to me that there's a group of bandits that are operating out of that cave. They were a problem for us before the cult arrived, but now they are a real terror. I can't spare the people to go and clear them out, unfortunately.\n\nI need you to go there and take care of them for me. Kill as many as you can, and if possible, take out their leader, the one they call \"Badwind\" Bennic. That cave is dangerous, so be careful.", sourceObjective = "Kill 10 Highlands Bandits and their leader, \"Badwind\" Bennic in the Shen'dar Highlands.", completion = "With the bandits dispersed, that is one less problem for us to deal with. Though I confess that now I worry that any bandits who survived may turn next to the cult for protection, further bolstering their increasingly alarming numbers.\n\nStill though, we'll take the victories where we can get them.", sourceObjectiveStatus = "unverified-source-field" }
quests[92519] = { id = 92519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ward Restocking", description = "Apothecary Jorell was supposed to bring us a case of antidotes and elixirs days ago, but we're still empty handed. That fool has probably poisoned himself again by brewing in that poorly-ventilated shack he calls his lab.\n\nIf you want to further help our ward, you would be a far more reliable individual for this job.\n\nFollow the road to Go'shek farm, south and a bit west of here. You'll likely find it packed and ready to go, with Jorell either missing or unconcerned with his obligations.", sourceObjective = "Pick up a case of Packaged Tonics at Jorell's lab in Go'shek Farm and return to Doctor Gregory Victor in Hammerfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[92528] = { id = 92528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Among the Faithful", description = "The faithful of Al'Akir grow ever stronger with each eager new recruit like yourself. As you can see, our strength gives form to the storm itself!\n\nNormally I'd send you straight to Skypriest Aanders for assessment, but he is occupied at present receiving a guest at the inn on the north side of town. Please avoid that place for now. An unshaven recruit like yourself in the presence of such a guest would be inappropriate.\n\nFor now, just don't get in anyone's way.", sourceObjective = "Look around Falaath Village to learn about the cult's intentions in the Shen'dar Highlands.", progress = "What did you learn?", completion = "Lorthuna herself was there? She's the leader of the whole damned cult!\n\nIf they are making a move on Shen'dar Village and the western watchtower, we've got to be ready. What is strange is... why the watchtower?\n\nThe Village I can understand, but the tower? It doesn't have much strategic significance, other than as a minor lookout post.\n\nRegardless, we will be prepared for them. They'll find that highlanders aren't as easy to catch flat footed as they might think.", sourceObjectiveStatus = "unverified-source-field" }
quests[92529] = { id = 92529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falaath Village", description = "It gladdens my heart that you wish to serve Al'Akir. Our current trials as a people stem from our own complacency. We grew prideful and took the bounty of the winds for granted. The stagnation that followed is the reason the spirits of the wind abandoned us.\n\nOnly through acts of contrition may we feel the wind's caress once more. If you seek the fellowship of like-minded shen'dorei, go to Falaath Village and find Missionary Jasaan there. I will mark you so that the faithful will know you as a recruit.", sourceObjective = "Report to Missionary Jasaan near the entrance to Falaath Village.\n\nIf you lose your Mark of Akir, speak with Sania Silverstream in Shen'dar Village to regain the effect.", completion = "What is this? A new acolyte seeking to serve the windlord sent by sister Sania? Truly we are blessed by the touch of the four winds this day!\n\nWe welcome all who seek to bask in the blessings of Al'Akir.", sourceObjectiveStatus = "unverified-source-field" }
quests[92532] = { id = 92532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warrior's Path", description = "While you were gone our warrior trainer--Blademaster Ren--requested that we send you their way when you returned. She dropped this note off for you as well.\n\nGive it a read, then find Blademaster Ren inside the village watchtower.", sourceObjective = "Read the Crumpled Note you've been given, then seek out Blademaster Ren inside the Thendal Village watchtower.", progress = "So you've come for training, then?", completion = "You are about to embark upon a dangerous journey. Our world is changing and it will need those who have the will to lead and protect others if our people hope to survive. As you grow in power you will need guidance. Come to me--I will do what I can to train you as you progress.\n\nGood luck, {name}, may the winds guide you.", sourceObjectiveStatus = "unverified-source-field" }
quests[92534] = { id = 92534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "jktestquest1a" }
quests[92544] = { id = 92544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Al'Aketh Thugs", description = "A band of Al'Aketh cult ruffians have taken up residence near the temple ruins just southwest of here, led by a real monster called Malduko Cloudcrush. This rabble has no doubt been dispatched here by High Priestess Lorthuna at the Shrine of Akir to attack travelers and coerce our people into joining the cult.\n\nI need to stay here at my post to alert travelers leaving the grove of the danger, but I would be grateful if you could do something about those cultists and their leader for me.", sourceObjective = "Slay 6 Al'Aketh Brutes, 4 Al'Aketh Neophytes, and Malduko Cloudcrush in Thendal Grove.", progress = "I suspect that seeing a few of their fellows bleeding on the ground will do wonders to dissuade any zealous ambitions these thugs might have had.", completion = "It was all I could do to stop myself from going over and joining you from my position here. I can only hope that these louts got the message and clear out of here soon. \n\nThank you, {class}. You have the gratitude of the Rangers of Thendal Grove.", sourceObjectiveStatus = "unverified-source-field" }
quests[92550] = { id = 92550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Havoc in the Highlands", description = "Our best defense here might just be a strong offense. The advantage we now have is that we expect an attack is coming. What they won't expect is for us to hit them first.\n\nI've already asked a lot of you, but please head back over to Falaath Village. Kill as many cultists as you can and if you can get close enough, kill the commander and bring me his head. I'll stay here and organize the citizens and our few peacekeepers to prepare a defense... just in case you don't return.", sourceObjective = "Travel to the ruins of Falaath Village and slay 6 Al'Aketh Stormcallers, 4 Living Lightning and take the head of Commander Cyclas.", progress = "It feels good to turn the tables on these zealots.", completion = "Thank the winds you've returned!\n\nSania Silverstream snuck out of town just before you returned, no doubt fleeing at the sight of our people arming themselves.\n\nYou've done an incredible thing for the people of Shen'dar Village and we owe you a debt of gratitude. If the cult returns to the highlands, they will find that Shen'dar is not such an easy target.\n\nWinds guide you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[92551] = { id = 92551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Supplies", description = "I overheard you might be going to Falaath Village? While you are there, please keep an eye out for our stolen supply caches.\n\nThe Al'Aketh have been raiding our supply caravans carrying various goods such as food and windstones to and from the lowlands for months. They've been blaming the bandits, of course, but we all know that it all ends up in the same place. If there's any of that stuff left in Falaath, it would be a huge help if you could recover it.", sourceObjective = "Collect 10 packs of Stolen Shen'dar Supplies from Falaath Village in the Shen'dar Highlands.", progress = "There's a lot of hungry and desperate skyborne here who need these supplies.", completion = "This is great! We've been barely squeaking by without our regular supply deliveries. I'll work with the constable to ensure that these supplies get redistributed to the townsfolk who are in most dire need.", sourceObjectiveStatus = "unverified-source-field" }
quests[92553] = { id = 92553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restocking the Larders", description = "Up for a bit of work? I could use a bit of muscle from a strong adventuring-type such as yourself. With how dangerous things are getting around here, no one's had much time to hunt or forage of late, and I need someone to get out there and source me fresh eggs and strider meat to keep this village fed.\n\nI'd be happy to teach you one of my famous recipes if you can bring me what I need. What do you say?", sourceObjective = "Collect 3 Small Eggs and 8 Strider Meat from creatures found throughout the Shen'dar Highlands.", progress = "No matter how much things change here on Zephras and how uncertain things get, I always say that a pipe full of dried peacebloom and nice full belly is a comfort that can't be beat!", completion = "These eggs aren't easy to get but wind save me, they are DELICIOUS fried up in a bit of ursera tallow.\n\nIf you've got a bit of time to spare and you enjoy cooking, I can teach you a few tips and tricks I've picked up. Say the word and I'd be happy to train you.", sourceObjectiveStatus = "unverified-source-field" }
quests[92579] = { id = 92579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Valanaar", description = "For now it seems the pylon and the village are safe, so I'd like you to deliver this report to the Valennia Stormfist in Valanaar, at the southeastern edge of the island. Valennia is the leader of the peacekeepers on the island and she needs to know what happened here.\n\nThe cult is expanding rapidly and the peacekeepers have avoided direct conflict until now, but those days are over. Valanaar will need to be ready for a fight.\n\nAt any rate, thank you. You'll always have friends in Shen'dar, {name}.", sourceObjective = "Deliver Aonda's Written Report to Valennia Stormfist in Valanaar.", progress = "A letter from Aonda. What's that crafty highlander been up to?", completion = "<Valennia's expression darkens as she reads the letter.>\n\nAonda trusted you to deliver this and she speaks highly enough of you in this letter, so I'll try to trust you too. Before we speak further, I need to consult with the few peacekeepers we have left here and formulate a plan in case the cult strikes here next. Enjoy your stay in Valanaar for now.\n\nIf you are looking to keep yourself busy, there are plenty of townsfolk that can likely use the help of a strong young adventurer like yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[92595] = { id = 92595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Windshapers", description = "<Illaya smiles warmly at you.>\n\nI am glad you returned to speak with me, child of the winds. I knew it the first moment you walked into my presence, that you were strong in the skysight. Do you find this surprising? Even those who have not trained as a Shaman may possess the gift. \n\nCome, let us speak about the mandate of the Windshapers, the nature of our struggles on Zephras, and the plight of our people.", sourceObjective = "Listen to what Illaya Amberwind has to say.", progress = "The world is changing and the path forward will be difficult. We have but one chance to save ourselves.", completion = "I think you now understand how important the mission of the Windshapers is. Every soul who commands the skysight is of vital importance if we hope to establish dialogue with the spirits of the winds once again.\n\nBetween threats from within such as the Al'Aketh, and the uncertainty of our safety here in Skywall, it is our responsibility as Windshapers to use our gifts to save our home and ensure that the Shen'dorei can survive these trying times.", sourceObjectiveStatus = "unverified-source-field" }
quests[92596] = { id = 92596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Order", description = "The aura of arcane energy that surrounds you is strong, even though you are not initiated as a mage. I am quite sure that you are going to be a capable adventurer, and your connection with our ancient magic will only ever be a boon to you even if you were to never utter a single word of power in spellcasting.\n\nCome, let us sit and speak some on my order, the nature of the arcane here on Zephras, and the plight of our people.", sourceObjective = "Have a seat and speak with Rathiril Sunlance.", progress = "Our land is going through changes, but there may yet be some good to come of this.", completion = "The High Order's mission is vital to the survival of our people. We hold our elemental benefactors in the utmost regard, but we must face reality; they are gone now, and we are on our own.\n\nBetween threats from within such as the Al'Aketh, and uncertainties of our security on this plane, it is our destiny as Highborne descendants of our ancestral home of Eldre'Thalas to use our gifts to ensure that the shen'dorei can stand on our own once again.", sourceObjectiveStatus = "unverified-source-field" }
quests[92597] = { id = 92597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reading the Ley Lines", description = "Here in the elemental plane, we derive much of our arcane strength from ley lines that still run through the ground under our feet. Of late, these ley lines have begun to pierce the surface, giving us more direct and powerful access to these latent arcane energies.\n\nGo to the standing stones to the northeast. There is a ley line there. Tap into your birthright and draw in its energy.", sourceObjective = "Use your Read Ley Line racial ability at the ley line in Thendal Grove.", completion = "Do you feel it? Yes? Good! You have taken your first steps. You'll find that with your abilities, you will be able to tap into latent magical energy in many locations. Doing so will provide a myriad of benefits, some profound, others more subtle. You won't know until you tap into them, But that's the best part of the gift... making the unknown known.\n\nIf we are to survive these dire times, we must be unwavering in our search for knowledge... and power.", sourceObjectiveStatus = "unverified-source-field" }
quests[92598] = { id = 92598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gift of Skysight", description = "As a Windshaper, you have the ability to use the sacred skysight gifted to us by the elemental spirits. Travel to the standing stones to the northeast of the village. Find the elemental convergence there and use your gift.\n\nYou'll find that you may draw upon the skysight anywhere, but its boon is much more powerful if you do so in the presence of an elemental convergence. You may at times receive other bits of wisdom from the spirits that are drawn to such places of power, as well.", sourceObjective = "Use your Skysight racial ability at the Elemental Convergence in Thendal Grove.", completion = "Like a muscle, your skysight must be exercised if you hope to grow stronger in the gift. Leveraging your skysight to bridge the distance between the mortal and the spiritual may prove invaluable to you in your adventures.\n\nYou'd do well to remember what you've learned here today. Our ability to use our gifts to hear what the elements tell us could be the key to our survival.", sourceObjectiveStatus = "unverified-source-field" }
quests[92640] = { id = 92640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Times", description = "Since engaging the cult in the open is not viable, our best chance is going to be to use this opportunity to attack the shrine itself. We can take Lorthuna herself off the board before she can finish her part of this scheme.\n\nIt so happens that Valennia has been preparing a strategy for a potential assault on the Shrine for some time now. The only problem is, we will need help. \n\nSpeak with Valennia for the details.", sourceObjective = "Speak with Valennia Stormfist in Valanaar and follow her instructions.", completion = "Tensions between the Windshapers and High Order are high right now, but we couldn't hope to carry out this plan without both groups on board.", sourceObjectiveStatus = "unverified-source-field" }
quests[92642] = { id = 92642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupting Logistics", description = "Valennia only sent one person to help repel a full-scale assault... by the winds.\n\nYou don't look like much but I'll take what I can get. We need to inflict as much damage as possible to stop this soon. My people can't hold out much longer.\n\nGo down the hill and disrupt their logistics. Their healers are keeping the attackers coming, if we take them out we might be able to rally and push them back. Any other cultists you kill while you are out there are helpful as well.", sourceObjective = "Slay 4 Al'Aketh Healers and 8 Al'Aketh Brawlers in the Gustberry Lowlands.", completion = "You are still alive? Thank the winds for small miracles, I suppose.", sourceObjectiveStatus = "unverified-source-field" }
quests[92643] = { id = 92643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Turncoat", description = "There is a turncoat amongst the Al'Aketh. They claim to know the cult's true intentions for the island and want to come in, but will only do so with assurances of protection.\n\nThis defector is hiding at a secluded residence just northwest of Valanaar inside the highlands. I need someone who can discreetly go there, find the traitor, and escort him back to us. This might be a trap, but if this information is as important as this traitor claims, its worth some risk.", sourceObjective = "Find the cultist turncoat at the house just inside the highlands northwest of Valanaar.", completion = "<This man is clearly dead, killed by the assassins that you fought outside the house. As you kneel down to inspect the body you notice the glinting reflection of something shiny...>", sourceObjectiveStatus = "unverified-source-field" }
quests[92644] = { id = 92644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfortunate News", description = "<You reach beneath the still-warm body of the turncoat cultist and recover a small, glowing blue crystal. It appears to be damaged, but it may still be important. High Elder Shadowsong may be interested in this.>", sourceObjective = "Deliver the glowing crystal to Talanaanis Shadowsong in Valanaar.", progress = "You are back? And... alone?", completion = "The turncoat was already dead when you arrived, you say? This is unfortunate news.\n\n<You hand over the crystal you found on the dead cultist's body.>\n\nInteresting...", sourceObjectiveStatus = "unverified-source-field" }
quests[92645] = { id = 92645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Breaker", description = "This attack is going to be hard to repel unless we can take out the cult commander. Belguilos \"the Breaker\" they call her, and she's a veritable terror. She used to be a peacekeeper before the cult got out of control, and even then she was... off. As a cultist I can only imagine how much worse she could be now.\n\nI might just be sending you to your death, but someone needs to take Belguilos out if we are going to survive here. You can find her at the villa at the hill's base. Good luck, {class}.", sourceObjective = "Slay Commander Belguilos in the Gustberry Lowlands.", completion = "Belguilos is dead? Four winds bless you, {class}. \n\nWe might just make it out of this alive after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[92646] = { id = 92646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confront Lorthuna", description = "Lorthuna fled up to the spires above using some sort of portal. Ayessa and Elaadrin went in after her. That was just a few moments ago.\n\nI'm afraid I took one too many hits and this is where I stay. Go through the portal, find Ayessa and help them stop Lorthuna.\n\nUnless that help that Elaadrin and Ayessa said they sent for arrives soon, you are on your own from here. Good luck, {class}.", sourceObjective = "Take the portal to the Rohashi Spires overhead and join Elaadrin Evengale and Ayessa Dawnsinger in their confrontation with the High Priestess Lorthuna.", completion = "I sent a few of our healers to ensure that Valennia and her remaining forces made it back in one piece. She should be resting in the High Elder's residence now.\n\nMuln has already departed back to Azeroth, but he and I spoke of what is next for the Windshapers and our mission to Azeroth. Unfortunately, the island is more vulnerable than ever now and we need a plan to protect Zephras from what is to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[92679] = { id = 92679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Tithe", description = "H--Hello, stranger. You have the look of a capable adventurer about you. I...\n\n<The Skyborne man winces, clearly suffering terrible pain>\n\n...I was wondering if you were seeking employment? I came here to Valanaar to recruit fighters to help save my farm. If you are interested, please go find my wife Aamelia Windfield at our orchard to the west of Valanaar, in the lowlands.", sourceObjective = "Listen to what Alvarion Windfield has to say and find Aamelia Windfield at the Windfield Orchard.", progress = "What? Alvarion is alive?", completion = "<Aamelia listens while you explain what became of Alvarion.>\n\nAt least I know he's going to be safe in Valanaar.\n\nStranger, I hate to tell you this but I think my idiot husband likely just sent you here to die for nothing. If you have any sense at all, you should leave now. This isn't your fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[92682] = { id = 92682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Yourself Useful", description = "Oh, so you've got more courage than sense, then? Fine, I won't argue.\n\nFerauu and his goons aren't due to pick up their take of the harvest just yet, so I'm going to put you to work for your meals until they arrive.\n\nHead outside and gather today's batch of stormapples for me. Oh, and the bandits lurking around the stormapple trees... They think they are sneaky. They aren't. Kill them for me. \n\nLet's see what you've got in a fight.", sourceObjective = "Gather 10 Ripe Stormapples and slay 5 Hungry Bandits at the Windfield Orchard.", progress = "These bandits are more likely to double cross and steal from each other than they are to steal from normal folks. I bet if Ferauu knew some of his people went rogue and came here early to tamper with the harvest, he'd kill them himself.", completion = "I watched you take down those bandits from the window. Not bad.", sourceObjectiveStatus = "unverified-source-field" }
quests[92683] = { id = 92683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flutterfly Dust", description = "I'm sure you've noticed the giant flutterflies out in the outer fields near the orchard? They are pleasant to look at, but they also have other benefits; namely their wing dust. It can be a mess, but if you can gather it up in large amounts, it has useful household applications.\n\nTake this Flutterfly Swatter and give the big bugs a good swat for me. They'll usually just get scared and flee, but sometimes they'll take some offense. Either way, they'll give their rumps a shake and drop a pile of dust.", sourceObjective = "Gather 5 Flutterfly Dust from the Flutterflies around the Gustberry Lowlands.", progress = "Flutterflies are normally docile and calm, but rub them the wrong way and sometimes they'll surprise you.", completion = "This stuff can be a bit messy and it tends to get everywhere. You'll probably be shaking this out of your trousers for weeks, unfortunately. I do appreciate it, though. I've had this on my to-do list for weeks, but getting too far from the house when it's just me on my own with bandits lurking everywhere is a big risk.\n\nDon't bother asking me what I use this stuff for. Things. Stuff and things. Don't worry about it.", sourceObjectiveStatus = "unverified-source-field" }
quests[92684] = { id = 92684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ornery Ornery Galestriders", description = "As if the harvest wasn't light enough this year already, the galestriders in the area have been getting into the orchard and stealing my stormapples. Think you can head out to the fields and cull them for me?\n\nTake care though stranger, these lowlands galestriders are bigger and angrier than the highlands variety. Watch yourself. A well timed kick is all it takes to put you down for good if you aren't paying attention.\n\nBring me some of their meat and I can make us a hot meal with it as well.", sourceObjective = "Gather 7 Lowlands Galestrider Tenderloins from the Ornery Galestriders found throughout the Gustberry Lowlands.", progress = "I don't think I've had real meat for dinner in... well, too long.", completion = "These are big tenderloins! You must have taken down some real monsters out there.", sourceObjectiveStatus = "unverified-source-field" }
quests[92685] = { id = 92685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hills Have Eyes", description = "The bandits have camps all over and there's a small one in the hills just north of here. Head up there and start cracking skulls. If we can catch them off guard and take them out before they come for us, we might just even the odds enough to stand a chance.\n\nBring me their masks. The bloodier the better.", sourceObjective = "Loot 7 Blood-Stained Bandit Masks from Highwayman Bandits in the Gustberry Lowlands.", progress = "If you manage to bring me enough bandit masks, maybe I'll stitch a blanket out of them and give it to Ferauu.\n\n<Aamelia laughs loudly.>", completion = "When I said the bloodier the better, you really listened. Good. It lets me know you made it hurt.\n\nOn a serious note, thank you for what you've done so far. I've been floating aimlessly around this farm for weeks as if I was just waiting for the end to come. I think I'm starting to have hope again.\n\nFerauu and his thugs are due any time now. All that's left is to go out and face them. What do you say, will you see this through to the end with me?", sourceObjectiveStatus = "unverified-source-field" }
quests[92693] = { id = 92693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standing Our Ground", description = "You've done a lot to give us a fighting chance. Even if we die today, we'll at least know we gave it our best shot.\n\nThis is your last chance, stranger. If you want to head back to Valanaar and live another day, I wouldn't blame you.\n\nOn the other hand, if you really have a thing for lost causes just let me know when you are ready to go. We'll walk out there with our heads held high and whatever happens, happens.", sourceObjective = "Speak with Aamelia Windfield when you are ready to confront the bandit leader.", progress = "There's not enough stormapples in skywall to repay you for this.", completion = "I... can't believe it's over. I need to stop and calm myself before my heart leaps right out of my chest.", sourceObjectiveStatus = "unverified-source-field" }
quests[92698] = { id = 92698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Is My Purpose?", description = "<You lean in close to try and hear the words coming from beneath the giant construct's armor plates.>\n\n...Function error...\n\n...Question...\n\n...What is....\n\n...Function...\n\n<These fragmented words and phrases seem to just repeat. Maybe someone nearby knows more about this construct?>", sourceObjective = "Speak with Aamelia Windfield about the Malfunctioning Cyclone Construct.", completion = "The construct? It's been wandering around the fields for decades. Since the wind elementals left us, I think. Alvarion suspected that it used to haul harvests to market, or maybe tend to livestock back before this was an orchard. That could have been a thousand years ago though.\n\nIn the old days, the Windshapers used to maintain these constructs. We've talked about petitioning them to come and take a look at it, but it's never been a pressing concern to us. Mostly we just ignore it these days.", sourceObjectiveStatus = "unverified-source-field" }
quests[92699] = { id = 92699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Supreme Magister", description = "Now that you've arrived in Valanaar, you'll likely want to check in with the other members of the High Order here. The current Supreme Magister, Elaadrin Evengale and his people operate out of the lodge on the far southeastern part of Valanaar.\n\nYou should also take care, the High Order and Windshapers don't get along very well here. Be careful and give the Windshapers a good, wide berth. We've got enough to worry about with the cult, I won't tolerate faction violence in the streets of Valanaar.", sourceObjective = "Find Elaadrin Evengale in Valanaar.", completion = "Hello and welcome. Rathiril sent me a magical missive about you and he mentioned you had some promise.\n\nWith you standing before me now, I can see why he suggested you seek me out. You have a vibrant arcane aura about you. Few enough of us anymore have the aptitude, let alone the will, to do what is needed to save our home. Do you have the boldness and strength needed to aid The High Order?\n\nI suppose we will see.", sourceObjectiveStatus = "unverified-source-field" }
quests[92700] = { id = 92700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Skyseer", description = "Now that you've arrived in Valanaar, you'll likely want to check in with the other members of the Windshapers here. The current Grand Skyseer and her people operate out of the lodge near the center of Valanaar.\n\nYou should also be aware, the Windshapers and High Order don't get along very well in these parts. Be careful and give the High Order a good, wide berth. We've got enough to worry about with the cult, I won't tolerate faction violence in the streets of Valanaar.", sourceObjective = "Find Ayessa Dawnsinger in Valanaar.", completion = "Elder Amberwind sent me a message about you and your exploits in Shen'dar Village. You are most welcome here, friend.\n\nYou have a strong aura, and you clearly have a resonance with the spirits. Fewer and fewer of us have the skysight of late, and Zephras needs those with the gift if we are to survive these trying times. I am glad you have found your way to me.\n\nI look forward to further making your acquaintance.", sourceObjectiveStatus = "unverified-source-field" }
quests[92701] = { id = 92701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Valanaar", description = "For now it seems the pylon and the village are safe, so I'd like you to deliver this report to the Valennia Stormfist in Valanaar, at the southeastern edge of the island. Valennia is the leader of the peacekeepers on the island and she needs to know what happened here.\n\nThe cult is expanding rapidly and the peacekeepers have avoided direct conflict until now, but those days are over. Valanaar will need to be ready for a fight.\n\nAt any rate, thank you. You'll always have friends in Shen'dar, {name}.", sourceObjective = "Deliver Aonda's Written Report to Valennia Stormfist in Valanaar.", progress = "A letter from Aonda. What's that crafty highlander been up to?", completion = "<Valennia's expression darkens as she reads the letter.>\n\nAonda trusted you to deliver this and she speaks highly enough of you in this letter, so I'll try to trust you too. Before we speak further, I need to consult with the few peacekeepers I have left here and formulate a plan in case the cult strikes here next. Enjoy your stay in Valanaar for now.\n\nIf you are looking to keep yourself busy, there are plenty of townsfolk that can likely use the help of a strong young adventurer like yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[92703] = { id = 92703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver the News", description = "I guess it doesn't feel quite right to keep calling you stranger after all of this so... thank you, {name}. \n\nIf you wouldn't mind and are back out that way, please let Alvarion know what happened here. Also, tell him that once he's up on his feet he needs to bring a windshaper back here to look at that construct for us to make sure it's safe to have around our... our family.\n\n<Aamelia touches her belly gently.>\n\nHe doesn't know about this part. Let's just keep that bit between us for now.", sourceObjective = "Speak with Alvarion Windfield in Valanaar.", completion = "<Alvarion's eyes tear up as you finish retelling the story of what happened at the orchard.>\n\nI don't know how to thank you, friend. I came to Valanaar looking for hope. A vain hope, I was almost certain. But instead I found a hero. A real hero, like the stories from before we came to Skywall. \n\nI'll never forget what you did for us, {name}. You'll always be welcome at the Windfield home.", sourceObjectiveStatus = "unverified-source-field" }
